# -*- coding: utf-8 -*-
# 팟캐스트 글자 23개 언어 번역
#  · 새 파일 lib/podcast/podcast_text.dart (번역표: 한국어 글자 → 21개 언어, 영어는 원래대로)
#  · podText: 한국어 → 한국어 / 그 밖 → 번역표 → 없으면 영어
#  · 숫자·검색어가 들어가는 글자(3일 전 · 12분 남음 · 회차 40개 …)는 podFmt로 바꿔서 번역되게
#  · 아래 줄(속도·수면·회차·구독) 글자가 긴 언어도 안 넘치게 칸을 똑같이 나누고 길면 살짝 줄임
#  · 홈 '최근에 들었어요'의 '팟캐스트', 라디오 탭 '팟캐스트'도 같이 번역됨 (그 파일은 안 고쳐도 됨)
import os, sys, re, base64

P = {
    'pod': os.path.join('lib', 'podcast', 'podcast.dart'),
    'screens': os.path.join('lib', 'podcast', 'podcast_screens.dart'),
}
NEW = os.path.join('lib', 'podcast', 'podcast_text.dart')
TEXT = base64.b64decode('').decode('utf-8')


def fail(m):
    print('❌', m, '— 아무것도 저장하지 않았어요.')
    sys.exit(1)


D = {}
for k, p in P.items():
    if not os.path.exists(p):
        fail('파일이 없어요: ' + p)
    raw = open(p, 'rb').read().decode('utf-8')
    D[k] = {'s': raw.replace('\r\n', '\n'), 'crlf': '\r\n' in raw}
    D[k]['orig'] = D[k]['s']


def name(k):
    return os.path.basename(P[k])


def rep(k, label, old, new, done):
    s = D[k]['s']
    if done in s:
        print('✔', name(k), label, '(이미 돼 있음)')
        return
    if s.count(old) != 1:
        fail(f'{name(k)} {label} — 찾을 코드를 못 찾았어요 ({s.count(old)}곳)')
    D[k]['s'] = s.replace(old, new)
    print('✔', name(k), label)


def norm(x):
    return re.sub(r'\s+', ' ', x)


def rep_call(k, label, old_call, new_call, count=1):
    """podText(...) 부르는 곳을 찾아 바꾸기 (줄바꿈·띄어쓰기가 달라도 찾음)"""
    s = D[k]['s']
    if norm(new_call) in norm(s) and norm(old_call) not in norm(s):
        print('✔', name(k), label, '(이미 돼 있음)')
        return
    spans = []
    i = 0
    while True:
        j = s.find('podText(', i)
        if j < 0:
            break
        d, e = 0, j + 7
        while True:
            c = s[e]
            if c == '(':
                d += 1
            elif c == ')':
                d -= 1
                if d == 0:
                    break
            e += 1
        if norm(s[j:e + 1]) == norm(old_call):
            spans.append((j, e + 1))
        i = e
    if len(spans) != count:
        fail(f'{name(k)} {label} — 찾을 코드를 못 찾았어요 ({len(spans)}곳)')
    for a, b in reversed(spans):
        s = s[:a] + new_call + s[b:]
    D[k]['s'] = s
    print('✔', name(k), label)


# ── podcast.dart ──
k = 'pod'
rep(k, 'import 번역표', "import '../l10n/locale_holder.dart';\n",
    "import '../l10n/locale_holder.dart';\nimport 'podcast_text.dart';\n", done="import 'podcast_text.dart';")
rep(k, 'podText: 번역표에서 찾기 + podFmt',
    "/// 팟캐스트 글자: 한국어면 한국어, 그 밖은 영어 (번역은 3단계에서 23개 언어로)\n"
    "String podText(String ko, String en) => tr.localeName.startsWith('ko') ? ko : en;\n",
    "/// 팟캐스트 글자: 한국어면 한국어 / 그 밖은 번역표(podcast_text.dart) → 없으면 영어\n"
    "String podText(String ko, String en) {\n"
    "  final l = tr.localeName;\n"
    "  if (l.startsWith('ko')) return ko;\n"
    "  return podTr[ko]?[podLangOf(l)] ?? en;\n"
    "}\n"
    "\n"
    "/// 숫자·이름이 들어가는 글자: '{n}일 전'처럼 자리를 비워 두고 값을 넣기\n"
    "String podFmt(String ko, String en, Map<String, Object> v) {\n"
    "  var t = podText(ko, en);\n"
    "  v.forEach((key, x) => t = t.replaceAll('{$key}', '$x'));\n"
    "  return t;\n"
    "}\n",
    done='String podFmt(String ko, String en, Map<String, Object> v) {')
rep_call(k, '며칠 전', "podText('$days일 전', '$days days ago')",
         "podFmt('{n}일 전', '{n} days ago', {'n': days})")
rep_call(k, '날짜', "podText('${d.month}월 ${d.day}일', '${d.month}/${d.day}')",
         "podFmt('{m}월 {d}일', '{m}/{d}', {'m': d.month, 'd': d.day})")
rep_call(k, '시간·분', "podText('$h시간 $m분', '${h}h ${m}m')",
         "podFmt('{h}시간 {m}분', '{h}h {m}m', {'h': h, 'm': m})")
rep_call(k, '분', "podText('${m < 1 ? 1 : m}분', '${m < 1 ? 1 : m}m')",
         "podFmt('{m}분', '{m}m', {'m': m < 1 ? 1 : m})")

# ── podcast_screens.dart ──
k = 'screens'
rep_call(k, '검색 결과', "podText('\\'$_query\\' 검색 결과', 'Results for \"$_query\"')",
         "podFmt('\\'{q}\\' 검색 결과', 'Results for \"{q}\"', {'q': _query})")
rep_call(k, 'N위까지 보기', "podText('${list.length}위까지 보기', 'Show top ${list.length}')",
         "podFmt('{n}위까지 보기', 'Show top {n}', {'n': list.length})")
rep_call(k, '이어 듣기 남은 시간', "podText('${podDurText(left)} 남음', '${podDurText(left)} left')",
         "podFmt('{t} 남음', '{t} left', {'t': podDurText(left)})")
rep_call(k, '회차 N개', "podText('회차 ${eps.length}개', '${eps.length} episodes')",
         "podFmt('회차 {n}개', '{n} episodes', {'n': eps.length})")
rep_call(k, '회차 남은 시간',
         "podText('${podDurText(((total - ms) / 1000).round())} 남음', '${podDurText(((total - ms) / 1000).round())} left')",
         "podFmt('{t} 남음', '{t} left', {'t': podDurText(((total - ms) / 1000).round())})")
rep(k, '아래 줄: 칸을 똑같이 나누고 긴 글자는 살짝 줄이기',
    '    final c = on ? _strongOf(dark) : _mutedOf(dark);\n'
    '    return GestureDetector(\n'
    '      onTap: onTap,\n'
    '      behavior: HitTestBehavior.opaque,\n'
    '      child: Padding(\n'
    '        padding: const EdgeInsets.fromLTRB(12, 4, 12, 0),\n'
    '        child: Column(\n'
    '          mainAxisSize: MainAxisSize.min,\n'
    '          children: [\n'
    '            SizedBox(height: 22, child: Center(child: top ?? Icon(icon, color: c, size: 22))),\n'
    '            const SizedBox(height: 4),\n'
    '            Text(label,\n'
    '                style: TextStyle(\n'
    '                  color: c,\n'
    '                  fontSize: 10.5,\n'
    '                  fontWeight: on ? FontWeight.w700 : FontWeight.w500,\n'
    '                )),\n'
    '          ],\n'
    '        ),\n'
    '      ),\n'
    '    );\n',
    '    final c = on ? _strongOf(dark) : _mutedOf(dark);\n'
    '    // 칸을 똑같이 나눔 → 독일어·헝가리어처럼 글자가 길어도 안 넘침 (길면 그 칸 안에서 살짝 줄임)\n'
    '    return Expanded(\n'
    '      child: GestureDetector(\n'
    '        onTap: onTap,\n'
    '        behavior: HitTestBehavior.opaque,\n'
    '        child: Padding(\n'
    '          padding: const EdgeInsets.fromLTRB(4, 4, 4, 0),\n'
    '          child: Column(\n'
    '            mainAxisSize: MainAxisSize.min,\n'
    '            children: [\n'
    '              SizedBox(height: 22, child: Center(child: top ?? Icon(icon, color: c, size: 22))),\n'
    '              const SizedBox(height: 4),\n'
    '              FittedBox(\n'
    '                fit: BoxFit.scaleDown,\n'
    '                child: Text(label,\n'
    '                    maxLines: 1,\n'
    '                    style: TextStyle(\n'
    '                      color: c,\n'
    '                      fontSize: 10.5,\n'
    '                      fontWeight: on ? FontWeight.w700 : FontWeight.w500,\n'
    '                    )),\n'
    '              ),\n'
    '            ],\n'
    '          ),\n'
    '        ),\n'
    '      ),\n'
    '    );\n',
    done='// 칸을 똑같이 나눔 → 독일어·헝가리어처럼 글자가 길어도 안 넘침')

for k in D:
    s = D[k]['s']
    if s.count('(') != s.count(')') or s.count('{') != s.count('}') or s.count('[') != s.count(']'):
        fail(name(k) + ' 괄호가 안 맞아요')
# 숫자가 들어간 podText가 남았는지 (번역이 안 되는 곳)
for k in D:
    for m in re.finditer(r"podText\('[^']*\$", D[k]['s']):
        fail(f'{name(k)} 숫자가 들어간 글자가 아직 남았어요: {m.group(0)}')

changed = [k for k in D if D[k]['s'] != D[k]['orig']]
new_needed = (not os.path.exists(NEW)) or open(NEW, 'rb').read().decode('utf-8').replace('\r\n', '\n') != TEXT
if not changed and not new_needed:
    print('이미 적용돼 있어요')
    sys.exit(0)
for k in changed:
    s = D[k]['s']
    if D[k]['crlf']:
        s = s.replace('\n', '\r\n')
    open(P[k], 'wb').write(s.encode('utf-8'))
if new_needed:
    crlf = D['pod']['crlf']
    open(NEW, 'wb').write((TEXT.replace('\n', '\r\n') if crlf else TEXT).encode('utf-8'))
    print('✔ 새 파일:', NEW)
print('저장했어요:', ', '.join([name(k) for k in changed] + (['podcast_text.dart'] if new_needed else [])))
